cd /tmp/e2e && cat > debug.mjs <<'EOF'
import {chromium} from 'playwright';
const browser = await chromium.launch({args: ['--no-sandbox', '--disable-gpu', '--disable-dev-shm-usage', '--no-zygote', '--single-process']});
const page = await browser.newPage({viewport: {width: 1280, height: 640}});
const logs = [];
page.on('console', (m) => logs.push(m.type() + ': ' + m.text()));
page.on('pageerror', (e) => logs.push('pageerror: ' + e));
page.on('requestfailed', (r) => logs.push('failed: ' + r.url()));
await page.goto(process.argv[2], {waitUntil: 'networkidle'});
await page.waitForTimeout(3000);
await page.screenshot({path: '/tmp/e2e/shots/debug.png'});
console.log(logs.join('\n'));
console.log((await page.innerHTML('.viz-widget__plot')).slice(0, 1500));
await browser.close();
EOF
